import { expect, it } from "@effect/vitest";
import { Deferred, Effect, Ref, Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { boundedTraversal } from "./fixtures/wiki/bounded-traversal.js";

const Traversal = Schema.Struct({
  concurrency: Schema.Literals([1, 2, 3, 4]),
  count: Schema.Literals([1, 2, 3, 4, 5, 6, 7, 8]),
});

it.effect.prop(
  "traversal never exceeds its supplied bound and preserves input order",
  { scenario: Arbitrary.schema(Traversal) },
  ({ scenario }) =>
    Effect.gen(function* traversalBound() {
      const observed = yield* boundedTraversal(scenario);
      expect(observed.maximum).toBeGreaterThan(0);
      expect(observed.maximum).toBeLessThanOrEqual(scenario.concurrency);
      expect(observed.active).toBe(0);
      expect(observed.results).toEqual(
        Array.from({ length: scenario.count }, (_, index) => index)
      );
    })
);

it.effect(
  "closing the owner interrupts scoped child work before returning",
  () =>
    Effect.gen(function* childOwnership() {
      const started = yield* Deferred.make<boolean>();
      const interrupted = yield* Ref.make(0);
      yield* Effect.scoped(
        Effect.gen(function* ownChild() {
          yield* Deferred.succeed(started, true).pipe(
            Effect.andThen(Effect.never),
            Effect.onInterrupt(() =>
              Ref.update(interrupted, (count) => count + 1)
            ),
            Effect.forkScoped
          );
          yield* Deferred.await(started);
        })
      );
      expect(yield* Ref.get(interrupted)).toBe(1);
    })
);

import { Effect, Ref } from "effect";

export const boundedTraversal = Effect.fnUntraced(
  function* boundedTraversal(options: {
    readonly concurrency: number;
    readonly count: number;
  }) {
    const activity = yield* Ref.make({ active: 0, maximum: 0 });
    const input = Array.from({ length: options.count }, (_, index) => index);

    const results = yield* Effect.forEach(
      input,
      (index) =>
        Effect.acquireUseRelease(
          Ref.update(activity, (state) => ({
            active: state.active + 1,
            maximum: Math.max(state.maximum, state.active + 1),
          })),
          () => Effect.yieldNow.pipe(Effect.andThen(Effect.succeed(index))),
          () =>
            Ref.update(activity, (state) => ({
              ...state,
              active: state.active - 1,
            }))
        ),
      { concurrency: options.concurrency }
    );

    return { ...(yield* Ref.get(activity)), results };
  }
);

import { Effect, ManagedRuntime } from "effect";
import type { Ref } from "effect";

import { BoundaryResource } from "./boundary-resource.js";

export const makeForeignRuntimeBoundary = (options: {
  readonly acquired: Ref.Ref<number>;
  readonly released: Ref.Ref<number>;
}) => {
  const runtime = ManagedRuntime.make(BoundaryResource.layer(options));

  const read = Effect.gen(function* readBoundaryResource() {
    const resource = yield* BoundaryResource;

    return yield* resource.read;
  });

  return {
    close: runtime.dispose.bind(runtime),
    // @effect-diagnostics-next-line asyncFunction:off -- This foreign framework boundary exposes a native Promise API.
    read: async () => await runtime.runPromise(read),
  };
};

import { expect, it } from "@effect/vitest";
import { Effect, Ref, Result } from "effect";

import { makeForeignRuntimeBoundary } from "./fixtures/wiki/foreign-runtime-boundary.js";

it.effect(
  "a foreign boundary builds once, closes once, and refuses reuse",
  () =>
    Effect.gen(function* runtimeLifetime() {
      const acquired = yield* Ref.make(0);
      const released = yield* Ref.make(0);
      yield* Effect.acquireUseRelease(
        Effect.sync(() => makeForeignRuntimeBoundary({ acquired, released })),
        (boundary) =>
          Effect.gen(function* useForeignBoundary() {
            expect(yield* Ref.get(acquired)).toBe(0);
            expect(yield* Effect.tryPromise(boundary.read)).toBe("ready");
            expect(yield* Effect.tryPromise(boundary.read)).toBe("ready");
            expect(yield* Ref.get(acquired)).toBe(1);
            yield* Effect.promise(boundary.close);
            yield* Effect.promise(boundary.close);
            expect(yield* Ref.get(released)).toBe(1);

            const reused = yield* Effect.tryPromise(boundary.read).pipe(
              Effect.result
            );

            expect(Result.isFailure(reused)).toBe(true);
          }),
        (boundary) => Effect.promise(boundary.close)
      );
    })
);

import { expect, it } from "@effect/vitest";
import { Cause, Deferred, Effect, Exit, Fiber, Ref, Result } from "effect";

it.effect.each(["success", "failure", "interruption"])(
  "closes an acquired resource exactly once after %s",
  (outcome) =>
    Effect.gen(function* resourceExit() {
      const acquired = yield* Ref.make(0);
      const released = yield* Ref.make(0);
      const started = yield* Deferred.make<boolean>();

      const acquire = Effect.acquireRelease(
        Effect.sync(() => ({ name: "counted-resource" })).pipe(
          Effect.tap(() => Ref.update(acquired, (count) => count + 1)),
          Effect.tap(() => Deferred.succeed(started, true))
        ),
        () => Ref.update(released, (count) => count + 1)
      );

      const use = Effect.scoped(
        Effect.gen(function* useResource() {
          const resource = yield* acquire;
          expect(resource.name).toBe("counted-resource");

          if (outcome === "failure") {
            return yield* Effect.fail("expected-refusal");
          }

          if (outcome === "interruption") {
            return yield* Effect.never;
          }

          return resource.name;
        })
      );

      if (outcome === "interruption") {
        const fiber = yield* Effect.forkChild(use);
        yield* Deferred.await(started);
        yield* Fiber.interrupt(fiber);
        const exit = yield* Fiber.await(fiber);
        expect(Exit.isFailure(exit) && Cause.hasInterrupts(exit.cause)).toBe(
          true
        );
      } else {
        const result = yield* Effect.result(use);
        expect(Result.isFailure(result)).toBe(outcome === "failure");

        if (Result.isFailure(result)) {
          expect(result.failure).toBe("expected-refusal");
        }
      }

      expect(yield* Ref.get(acquired)).toBe(1);
      expect(yield* Ref.get(released)).toBe(1);
    })
);

import { expect, it } from "@effect/vitest";
import { Effect, Layer, Predicate, Ref, Schema } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";
import { OtlpSerialization, OtlpTracer } from "effect/observability";

const ExportedTrace = Schema.Struct({
  resourceSpans: Schema.Array(
    Schema.Struct({
      scopeSpans: Schema.Array(
        Schema.Struct({
          spans: Schema.Array(
            Schema.Struct({
              attributes: Schema.Array(
                Schema.Struct({ key: Schema.String, value: Schema.Unknown })
              ),
              name: Schema.String,
            })
          ),
        })
      ),
    })
  ),
});

it.effect(
  "scope shutdown exports named spans through the supplied transport",
  () =>
    Effect.gen(function* traceDelivery() {
      const deliveries = yield* Ref.make<
        readonly (typeof ExportedTrace.Type)[]
      >([]);

      const client = HttpClient.make((request) =>
        Effect.gen(function* receiveTelemetry() {
          if (!Predicate.isTagged(request.body, "Uint8Array")) {
            return yield* Effect.die("Expected serialized OTLP JSON bytes");
          }

          const text = new TextDecoder().decode(request.body.body);

          const trace = yield* Schema.decodeEffect(
            Schema.fromJsonString(ExportedTrace)
          )(text).pipe(Effect.orDie);

          yield* Ref.update(deliveries, (received) => [...received, trace]);

          return HttpClientResponse.fromWeb(request, new Response());
        })
      );

      const tracing = OtlpTracer.layer({
        resource: { serviceName: "wiki-fixture" },
        url: "https://collector.example.test/v1/traces",
      }).pipe(
        Layer.provide(OtlpSerialization.layerJson),
        Layer.provide(Layer.succeed(HttpClient.HttpClient, client))
      );

      yield* Effect.scoped(
        Effect.void.pipe(
          Effect.withSpan("fixture.read"),
          Effect.annotateSpans({ phase: "read" }),
          Effect.provide(tracing)
        )
      );

      const spans = (yield* Ref.get(deliveries)).flatMap((delivery) =>
        delivery.resourceSpans.flatMap((resource) =>
          resource.scopeSpans.flatMap((scope) => scope.spans)
        )
      );

      expect(spans.map((span) => span.name)).toContain("fixture.read");
      expect(
        spans.flatMap((span) =>
          span.attributes.map((attribute) => attribute.key)
        )
      ).toContain("phase");
    })
);

import { Effect, Schema } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";

const Reply = Schema.Struct({ version: Schema.Int });

export class ResponseFixtureError extends Schema.TaggedError<ResponseFixtureError>()(
  "ResponseFixtureError",
  { cause: Schema.Defect(), phase: Schema.Literals(["status", "body"]) }
) {}

export const readValidatedResponse = Effect.fn("readValidatedResponse")(
  function* readValidatedResponse() {
    const client = (yield* HttpClient.HttpClient).pipe(
      HttpClient.filterStatusOk
    );

    const response = yield* client
      .get("https://provider.example.test/version")
      .pipe(
        Effect.mapError(
          (cause) => new ResponseFixtureError({ cause, phase: "status" })
        )
      );

    return yield* HttpClientResponse.schemaBodyJson(Reply)(response).pipe(
      Effect.mapError(
        (cause) => new ResponseFixtureError({ cause, phase: "body" })
      )
    );
  }
);

import { expect, it } from "@effect/vitest";
import { Effect, Result } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";

import { readValidatedResponse } from "./fixtures/validated-http-response.js";

it.effect.each([
  { body: '{"version":4}', expected: "success", status: 200 },
  { body: '{"version":4}', expected: "status", status: 503 },
  { body: "{", expected: "body", status: 200 },
  { body: '{"version":"four"}', expected: "body", status: 200 },
])("checks status and decoded shape: $expected ($status, $body)", (scenario) =>
  Effect.gen(function* validateResponse() {
    const client = HttpClient.make((request) =>
      Effect.sync(() =>
        HttpClientResponse.fromWeb(
          request,
          new Response(scenario.body, {
            headers: { "content-type": "application/json" },
            status: scenario.status,
          })
        )
      )
    );

    const result = yield* readValidatedResponse().pipe(
      Effect.provideService(HttpClient.HttpClient, client),
      Effect.result
    );

    if (Result.isFailure(result)) {
      expect(result.failure._tag).toBe("ResponseFixtureError");
      expect(result.failure.phase).toBe(scenario.expected);
    } else {
      expect(scenario.expected).toBe("success");
      expect(result.success.version).toBe(4);
    }
  })
);

