export const RUNNER_SOURCE = String.raw`
import { createInterface } from "node:readline";
import { createContext, Script } from "node:vm";
const logs = [];
const parentPid = process.ppid;
const exitIfOrphaned = () => {
  if (process.ppid === 1 || process.ppid !== parentPid) process.exit(1);
};
exitIfOrphaned();
setInterval(exitIfOrphaned, 250).unref();
process.stdin.on("end", () => process.exit(1));
process.stdin.on("close", () => process.exit(1));
const evaluationOptions = { timeout: 1000 };
let deadline;
let expiresAt = 0;
const evaluationTimeout = () => Math.max(1, Math.min(evaluationOptions.timeout, expiresAt - Date.now()));
const send = (message) => new Promise((resolve, reject) => {
  process.stdout.write(JSON.stringify(message) + "\n", (error) => {
    if (error) reject(error);
    else resolve();
  });
});
const context = createContext(Object.create(null), {
  codeGeneration: { strings: false, wasm: false },
  microtaskMode: "afterEvaluate",
});
context.__hostCall = (id, name, input) => {
  send({ type: "call", id, name, input: JSON.parse(input) }).catch(() => process.exit(1));
};
context.__hostLog = (level, text) => {
  logs.push(level + ": " + text);
};
context.__hostDone = (encoded) => {
  const outcome = JSON.parse(encoded);
  send({ ...outcome, logs }).then(
    () => process.exit(0),
    () => process.exit(1)
  );
};
const bridge = new Script([
  "(() => {",
  "  const hostCall = globalThis.__hostCall;",
  "  const hostLog = globalThis.__hostLog;",
  "  const hostDone = globalThis.__hostDone;",
  "  delete globalThis.__hostCall;",
  "  delete globalThis.__hostLog;",
  "  delete globalThis.__hostDone;",
  "  const parse = JSON.parse;",
  "  const stringify = JSON.stringify;",
  "  const ContextError = Error;",
  "  const assign = Object.assign;",
  "  const pending = new Map();",
  "  let nextId = 1;",
  "  const names = [];",
  "  const configure = (encoded) => names.push(...parse(encoded));",
  "  const tools = new Proxy(Object.create(null), {",
  "    ownKeys: () => names,",
  "    getOwnPropertyDescriptor: (_target, name) => names.includes(name) ? { configurable: true, enumerable: true } : undefined,",
  "    get: (_target, name) => {",
  '      if (typeof name !== "string") return undefined;',
  "      return (input) => new Promise((resolve, reject) => {",
  "        const id = nextId++;",
  "        pending.set(id, { resolve, reject });",
  "        hostCall(id, name, stringify(input === undefined ? {} : input));",
  "      });",
  "    },",
  "  });",
  '  const capture = (level) => (...parts) => hostLog(level, parts.map((part) => typeof part === "string" ? part : stringify(part)).join(" "));',
  '  const console = Object.freeze({ debug: capture("debug"), error: capture("error"), info: capture("info"), log: capture("log"), warn: capture("warn") });',
  "  const deliver = (id, encoded) => {",
  "    const waiter = pending.get(id);",
  "    pending.delete(id);",
  "    if (waiter === undefined) return;",
  "    const message = parse(encoded);",
  "    if (message.ok) waiter.resolve(message.value);",
  "    else {",
  '      const error = new ContextError((message.error && message.error.message) || "capability failed");',
  "      assign(error, message.error);",
  "      waiter.reject(error);",
  "    }",
  "  };",
  "  const execute = async (program) => {",
  "    try {",
  "      const result = await program(tools, console);",
  '      hostDone(stringify({ type: "done", result: result === undefined ? null : result }));',
  "    } catch (error) {",
  '      hostDone(stringify({ type: "error", message: error instanceof Error ? error.message : String(error) }));',
  "    }",
  "  };",
  "  return { tools, console, deliver, execute, configure };",
  "})()",
].join(String.fromCharCode(10))).runInContext(context, evaluationOptions);
const rl = createInterface({ input: process.stdin });
rl.on("close", () => process.exit(1));
process.stdin.on("error", () => process.exit(1));
process.stdout.on("error", () => process.exit(1));
rl.on("line", (line) => {
  if (line.trim() === "") return;
  const message = JSON.parse(line);
  if (message.type === "result") {
    try {
      context.__deliver = bridge.deliver;
      context.__deliveryId = message.id;
      context.__delivery = JSON.stringify(message);
      new Script("(() => { const deliver = globalThis.__deliver; const id = globalThis.__deliveryId; const encoded = globalThis.__delivery; delete globalThis.__deliver; delete globalThis.__deliveryId; delete globalThis.__delivery; deliver(id, encoded); })()").runInContext(context, { timeout: evaluationTimeout() });
    } catch (error) {
      send({ type: "error", reason: error.code === "ERR_SCRIPT_EXECUTION_TIMEOUT" ? "timeout" : "threw", message: error.message, logs }).then(() => process.exit(0), () => process.exit(1));
    }
    return;
  }
  if (message.type !== "run") return;
  if (deadline !== undefined) return;
  const timeoutMillis = Math.max(1, Math.floor(Math.min(message.timeoutMillis, 2147483647)));
  expiresAt = Date.now() + timeoutMillis;
  deadline = setTimeout(() => process.exit(1), timeoutMillis);
  try {
    bridge.configure(JSON.stringify(message.names));
    context.__execute = bridge.execute;
    new Script("(() => { const execute = globalThis.__execute; delete globalThis.__execute; execute(async function(tools, console) {" + String.fromCharCode(10) + message.code + String.fromCharCode(10) + "}); })()").runInContext(context, { timeout: evaluationTimeout() });
  } catch (error) {
    const outcome = {
      type: "error",
      reason: error.code === "ERR_SCRIPT_EXECUTION_TIMEOUT" ? "timeout" : "threw",
      message: error instanceof Error ? error.message : String(error),
    };
    send({ ...outcome, logs }).then(
      () => process.exit(0),
      () => process.exit(1)
    );
  }
});
`;

const ChildMessage = Schema.Union([
  Schema.Struct({
    id: Schema.Finite,
    input: Schema.Json,
    name: Schema.String,
    type: Schema.Literal("call"),
  }),
  Schema.Struct({
    logs: Schema.Array(Schema.String),
    result: Schema.Unknown,
    type: Schema.Literal("done"),
  }),
  Schema.Struct({
    logs: Schema.Array(Schema.String),
    message: Schema.String,
    reason: Schema.optional(Schema.Literals(["threw", "timeout"])),
    type: Schema.Literal("error"),
  }),
]);

const decodeChildMessage = Schema.decodeUnknownEffect(
  Schema.fromJsonString(ChildMessage)
);

type HostMessage =
  | {
      readonly code: string;
      readonly names: readonly string[];
      readonly timeoutMillis: number;
      readonly type: "run";
    }
  | ({ readonly id: number; readonly type: "result" } & InvokeOutcome);

const encoder = new TextEncoder();

const isSandboxError = Schema.is(SandboxError);

export interface SubprocessOptions {
  readonly timeout?: Duration.Input | undefined;
  readonly nodePath?: string | undefined;
}

const makeSubprocess = (options?: SubprocessOptions) =>
  Effect.gen(function* makeSubprocessSandbox() {
    const spawner = yield* ChildProcessSpawner.ChildProcessSpawner;
    const timeout = Duration.fromInputUnsafe(options?.timeout ?? "10 seconds");
    const nodePath = options?.nodePath ?? process.execPath;

    const command = ChildProcess.make(
      nodePath,
      [
        "--permission",
        "--disallow-code-generation-from-strings",
        "--input-type=module",
        "-e",
        RUNNER_SOURCE,
      ],
      {
        detached: true,
        env: {},
        extendEnv: false,
        forceKillAfter: "250 millis",
        killSignal: "SIGTERM",
      }
    );

    const run = Effect.fn("Sandbox.run")(function* run(
      code: string,
      invoke: Invoke,
      names: readonly string[]
    ) {
      const handle = yield* spawner.spawn(command).pipe(
        Effect.mapError(
          (error) =>
            new SandboxError({
              logs: [],
              message: error.message,
              reason: "exited",
            })
        )
      );

      const outbox = yield* Queue.unbounded<Uint8Array, Cause.Done>();
      yield* Stream.fromQueue(outbox).pipe(
        Stream.run(handle.stdin),
        Effect.ignore,
        Effect.forkScoped
      );

      const send = (message: HostMessage) =>
        Queue.offer(outbox, encoder.encode(`${JSON.stringify(message)}\n`));

      yield* send({
        code,
        names,
        timeoutMillis: Duration.toMillis(timeout),
        type: "run",
      });

      const outcome = yield* Stream.decodeText(handle.stdout).pipe(
        Stream.splitLines,
        Stream.filter((line) => line.trim() !== ""),
        Stream.mapEffect((line) =>
          decodeChildMessage(line).pipe(
            Effect.mapError(
              (error) =>
                new SandboxError({
                  logs: [],
                  message: `Unreadable sandbox message: ${error.message}`,
                  reason: "protocol",
                })
            ),
            Effect.flatMap((message) => {
              if (message.type === "call") {
                return invoke(message.name, message.input).pipe(
                  Effect.flatMap((result: InvokeOutcome) =>
                    send({ id: message.id, type: "result", ...result })
                  ),
                  Effect.andThen(Effect.succeedNone)
                );
              }

              return Effect.succeedSome<SandboxRun | SandboxError>(
                message.type === "done"
                  ? { logs: message.logs, result: message.result }
                  : new SandboxError({
                      logs: message.logs,
                      message: message.message,
                      reason: message.reason ?? "threw",
                    })
              );
            })
          )
        ),
        Stream.filter(Option.isSome),
        Stream.map((option) => option.value),
        Stream.runHead,
        Effect.mapError((error) =>
          isSandboxError(error)
            ? error
            : new SandboxError({
                logs: [],
                message: error.message,
                reason: "exited",
              })
        )
      );

      if (Option.isNone(outcome)) {
        return yield* new SandboxError({
          logs: [],
          message: "The sandbox exited before finishing the program",
          reason: "exited",
        });
      }

      if (isSandboxError(outcome.value)) {
        return yield* outcome.value;
      }

      return outcome.value;
    }, Effect.scoped);

    return {
      run: (code: string, invoke: Invoke, names: readonly string[] = []) =>
        run(code, invoke, names).pipe(
          Effect.timeoutOrElse({
            duration: timeout,
            orElse: () =>
              Effect.fail(
                new SandboxError({
                  logs: [],
                  message: `The program did not finish within ${Duration.format(timeout)}`,
                  reason: "timeout",
                })
              ),
          })
        ),
    } as const;
  });

export const layerSubprocess = (
  options?: SubprocessOptions
): Layer.Layer<Sandbox, never, ChildProcessSpawner.ChildProcessSpawner> =>
  Layer.effect(Sandbox, makeSubprocess(options));

// @effect-diagnostics anyUnknownInErrorContext:off unsafeEffectTypeAssertion:off missingEffectContext:off -- See to-toolkit.ts: a projection over a heterogeneous list erases error and requirement types at the boundary and recovers them for callers.
import type { Layer } from "effect";
import { Effect, Schema } from "effect";
import { Tool, Toolkit } from "effect/ai";

import { searchCatalog, toCatalog, toTypeScript } from "./catalog.js";
import type { Catalog } from "./catalog.js";
import { defineContract, failureSchemaOf } from "./contract.js";
import type {
  AnyCapability,
  ApprovalRequirement,
  ContractOf,
  FailureSchemaOf,
} from "./contract.js";
import { implement } from "./implement.js";
import { Sandbox, SandboxError, invokeFailure } from "./sandbox-service.js";
import type { Invoke, InvokeOutcome } from "./sandbox-service.js";
import type { RequirementsOf } from "./to-toolkit.js";

export const SearchMatch = Schema.Struct({
  description: Schema.String,
  name: Schema.String,
  score: Schema.Finite,
  signature: Schema.String,
});

export const SearchResult = Schema.Struct({
  matches: Schema.Array(SearchMatch),
  total: Schema.Int,
});

export const ExecuteInput = Schema.Struct({
  code: Schema.String,
});

export const ExecuteResult = Schema.Struct({
  logs: Schema.Array(Schema.String),
  result: Schema.Json,
});

const search = Tool.make("search", {
  description:
    "Find capabilities by intent. Returns each match's TypeScript signature for the `tools` object available to `execute`. Call this before `execute` when unsure what exists.",
  parameters: Schema.Struct({
    limit: Schema.optional(Schema.Int),
    query: Schema.String,
  }),
  success: SearchResult,
})
  .annotate(Tool.Readonly, true)
  .annotate(Tool.Idempotent, true);

const executeIntro =
  "Run a JavaScript program against the capabilities. The program is the body of an async function with `tools` in scope; `return` a JSON value to get it back, and `console.log` is captured into `logs`. Each `tools.<name>(input)` call is validated against that capability's input schema, runs on the host, and resolves with its output or rejects with its declared failure.";

const executeDescription = (
  declarations: string,
  placement: DeclarationPlacement
): string =>
  placement === "search"
    ? [
        executeIntro,
        "",
        "Call `search` first to get the TypeScript signature of each capability on the `tools` object, or read the host's declarations resource if it serves one.",
      ].join("\n")
    : [
        executeIntro,
        "",
        "The `tools` object:",
        "",
        "```ts",
        declarations.trimEnd(),
        "```",
      ].join("\n");

export type DeclarationPlacement = "inline" | "search";

export interface ExecuteOptions {
  readonly declarations?: DeclarationPlacement | undefined;
}

export interface CodeModeOptions extends ExecuteOptions {
  readonly searchLimit?: number | undefined;
}

type NeedsApprovalOf<Caps extends readonly AnyCapability[]> =
  true extends ContractOf<Caps[number]>["needsApproval"] ? true : false;

export interface CodeModeProjection<Caps extends readonly AnyCapability[]> {
  readonly catalog: Catalog;
  readonly declarations: string;
  readonly toolkit: Toolkit.Toolkit<{
    readonly search: typeof search;
    readonly execute: Tool.Tool<
      "execute",
      {
        readonly parameters: Schema.Struct<{ readonly code: Schema.String }>;
        readonly success: typeof ExecuteResult;
        readonly failure: FailureSchemaOf<
          typeof SandboxError,
          NeedsApprovalOf<Caps>
        >;
        readonly failureMode: "error";
      }
    >;
  }>;
  readonly layer: Layer.Layer<
    Tool.HandlersFor<CodeModeProjection<Caps>["toolkit"]["tools"]>,
    never,
    RequirementsOf<Caps> | ApprovalRequirement<NeedsApprovalOf<Caps>> | Sandbox
  >;
}

export const invokerFor = <const Caps extends readonly AnyCapability[]>(
  capabilities: Caps
): Effect.Effect<Invoke, never, RequirementsOf<Caps>> =>
  Effect.gen(function* buildInvoker() {
    const context = yield* Effect.context<RequirementsOf<Caps>>();

    const byName = new Map(
      capabilities.map(
        (capability) => [capability.contract.name, capability] as const
      )
    );

    const invoke: Invoke = (name, input) => {
      const item = byName.get(name);

      if (item === undefined) {
        return Effect.succeed(
          invokeFailure("UnknownCapability", `No capability named ${name}`)
        );
      }

      // SAFETY: `AnyCapability` erased this capability's requirements to `unknown`; they are a subset of `RequirementsOf<Caps>`, which `context` carries. The input is decoded by its schema first.
      // oxlint-disable-next-line typescript/no-unsafe-type-assertion
      const run = item.handler as (
        // oxlint-disable-next-line anti-slop/no-unknown-parameters
        input: unknown
      ) => Effect.Effect<unknown, unknown, RequirementsOf<Caps>>;

      const encodeOutput = Schema.encodeUnknownEffect(item.contract.output);

      const encodeFailure = Schema.encodeUnknownEffect(
        failureSchemaOf(item.contract)
      );

      return Schema.decodeUnknownEffect(item.contract.input)(input).pipe(
        Effect.matchEffect({
          onFailure: (error) =>
            Effect.succeed(invokeFailure("InvalidInput", error.message)),
          onSuccess: (decoded) =>
            run(decoded).pipe(
              Effect.provideContext(context),
              Effect.matchEffect({
                onFailure: (error) =>
                  encodeFailure(error).pipe(
                    Effect.map((encoded): InvokeOutcome => ({
                      error: encoded,
                      ok: false,
                    })),
                    Effect.orElseSucceed(() =>
                      invokeFailure("UnencodableFailure", String(error))
                    )
                  ),
                onSuccess: (output) =>
                  encodeOutput(output).pipe(
                    Effect.map((value): InvokeOutcome => ({
                      ok: true,
                      value,
                    })),
                    Effect.orElseSucceed(() =>
                      invokeFailure("UnencodableOutput", String(output))
                    )
                  ),
              })
            ),
        })
      );
    };

    return invoke;
  });

export const toExecuteCapability = <
  const Caps extends readonly [AnyCapability, ...AnyCapability[]],
>(
  capabilities: Caps,
  options?: ExecuteOptions
) => {
  const catalog = toCatalog(capabilities);
  const declarations = toTypeScript(catalog);

  const hasApproval = capabilities.some((item) => item.contract.needsApproval);
  // SAFETY: Caps preserves the literal approval flag for the generated capability, and `some` over the same array computes exactly that flag.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion
  const needsApproval = hasApproval as NeedsApprovalOf<Caps>;

  const executeContract = defineContract("execute", {
    annotations: {
      destructive: capabilities.some(
        (item) => item.contract.annotations.destructive
      ),
      openWorld: capabilities.some(
        (item) => item.contract.annotations.openWorld
      ),
      readOnly: capabilities.every(
        (item) => item.contract.annotations.readOnly
      ),
    },
    description: executeDescription(
      declarations,
      options?.declarations ?? "inline"
    ),
    failure: SandboxError,
    input: ExecuteInput,
    needsApproval,
    output: ExecuteResult,
  });

  const capability = implement(
    executeContract,
    Effect.fn("CodeMode.execute")(function* execute({ code }) {
      const invoke = yield* invokerFor(capabilities);

      const sandbox = yield* Sandbox;

      const run = yield* sandbox.run(
        code,
        invoke,
        catalog.capabilities.map((entry) => entry.name)
      );

      return {
        logs: run.logs,
        // SAFETY: every Sandbox implementation must JSON-round-trip a successful result before crossing this boundary.
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion
        result: run.result as typeof ExecuteResult.Type.result,
      };
    })
  );

  return { capability, catalog, declarations } as const;
};

export const toCodeMode = <
  const Caps extends readonly [AnyCapability, ...AnyCapability[]],
>(
  capabilities: Caps,
  options?: CodeModeOptions
): CodeModeProjection<Caps> => {
  const executeProjection = toExecuteCapability(capabilities, options);
  const { catalog, declarations } = executeProjection;
  const searchLimit = options?.searchLimit ?? 5;

  const execute = Tool.make("execute", {
    description: executeProjection.capability.contract.description,
    failure: failureSchemaOf(executeProjection.capability.contract),
    needsApproval: executeProjection.capability.contract.needsApproval,
    parameters: ExecuteInput,
    success: ExecuteResult,
  })
    .annotate(
      Tool.Readonly,
      capabilities.every(
        (capability) => capability.contract.annotations.readOnly
      )
    )
    .annotate(
      Tool.Destructive,
      capabilities.some(
        (capability) => capability.contract.annotations.destructive
      )
    )
    .annotate(
      Tool.OpenWorld,
      capabilities.some(
        (capability) => capability.contract.annotations.openWorld
      )
    );

  const toolkit = Toolkit.make(search, execute);

  const layer = toolkit.toLayer(
    Effect.gen(function* buildCodeModeHandlers() {
      const context = yield* Effect.context<
        RequirementsOf<Caps> | ApprovalRequirement<NeedsApprovalOf<Caps>>
      >();

      const sandbox = yield* Sandbox;

      return toolkit.of({
        execute: (input) =>
          executeProjection.capability
            .handler(input)
            .pipe(
              Effect.provideService(Sandbox, sandbox),
              Effect.provideContext(context)
            ),
        search: ({ limit, query }) => {
          const matches = searchCatalog(catalog, query, limit ?? searchLimit);

          return Effect.succeed({
            matches,
            total: catalog.capabilities.length,
          });
        },
      });
    })
  );

  return { catalog, declarations, layer, toolkit };
};

