import { Action } from "alchemy";
import type { Input } from "alchemy";
import { CurrentRuntimeContext, sanitizeKey } from "alchemy/RuntimeContext";
import {
  connectionSourceDigest,
  resolveConnectionSource,
} from "alchemy/SQL/ConnectionSource";
import type { StaticConnectionSource } from "alchemy/SQL/ConnectionSource";
import type { SqlExecutor } from "alchemy/SQL/Migrations/Format";
import { makePgMigrationExecutor } from "alchemy/SQL/Migrations/PgExecutor";
import {
  normalizeMigrationsInput,
  runMigrations,
} from "alchemy/SQL/Migrations/Registry";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Schema from "effect/Schema";

class PostgresMigrationConnectionError extends Schema.TaggedError<PostgresMigrationConnectionError>()(
  "PostgresMigrationConnectionError",
  { cause: Schema.Defect() }
) {}

interface MigrationInput {
  readonly databaseId: string;
  readonly directory: string;
  readonly schemaHash: string;
  readonly sourceDigest: string;
}

export const runPostgresMigrations = (
  directory: string,
  executor: SqlExecutor
) =>
  runMigrations({
    input: normalizeMigrationsInput(directory),
    stamped: {},
    withExecutor: (apply) => apply(executor),
  });

export const registerPostgresMigrations = (options: {
  readonly id: string;
  readonly databaseId: Input<string>;
  readonly directory: string;
  readonly schemaHash: Input<string>;
  readonly source: StaticConnectionSource;
}) =>
  Effect.gen(function* registerMigrations() {
    const Migrate = Action(
      "Database.PostgresMigrate",
      Effect.gen(function* makeRunner() {
        const connectionUrl = yield* resolveConnectionSource(options.source);

        return (input: MigrationInput) =>
          Effect.scoped(
            Effect.gen(function* applyMigrations() {
              const url = Redacted.value(yield* connectionUrl);

              const { Client } = yield* Effect.promise(
                // oxlint-disable-next-line promise-function-async -- Effect.promise consumes a Promise factory directly.
                () => import("pg")
              );

              return yield* Effect.acquireUseRelease(
                Effect.tryPromise({
                  catch: (cause) =>
                    new PostgresMigrationConnectionError({ cause }),
                  // @effect-diagnostics-next-line asyncFunction:off -- The pg client exposes Promise-based connection setup.
                  try: async () => {
                    const connection = new Client({ connectionString: url });

                    await connection.connect();

                    return connection;
                  },
                }),
                (connection) =>
                  runPostgresMigrations(
                    input.directory,
                    makePgMigrationExecutor(connection)
                  ),
                (connection) =>
                  Effect.tryPromise({
                    catch: (cause) =>
                      new PostgresMigrationConnectionError({ cause }),
                    // @effect-diagnostics-next-line asyncFunction:off -- The pg client exposes Promise-based shutdown.
                    try: async () => {
                      await connection.end();
                    },
                  }).pipe(Effect.orDie)
              );
            })
          );
      })
    );

    const result = yield* Migrate(`${options.id}-postgres-migrations`, {
      databaseId: options.databaseId,
      directory: options.directory,
      schemaHash: options.schemaHash,
      sourceDigest: connectionSourceDigest(options.source),
    });

    const runtimeContext = yield* CurrentRuntimeContext;

    if (runtimeContext !== undefined) {
      yield* runtimeContext.set(
        sanitizeKey(`${options.id}PostgresMigrations`),
        result
      );
    }
  });

import { runCheck } from "@rat-stack/check-harness";
import type { Verdict } from "@rat-stack/check-harness";
import { Clock, Effect, Schema } from "effect";
import * as HttpClient from "effect/http/HttpClient";
import * as HttpClientRequest from "effect/http/HttpClientRequest";
import * as HttpClientResponse from "effect/http/HttpClientResponse";

const ToolsResponse = Schema.Struct({
  result: Schema.Struct({
    tools: Schema.Array(Schema.Struct({ name: Schema.String })),
  }),
});

const ExecuteResponse = Schema.Struct({
  result: Schema.Struct({ id: Schema.String, text: Schema.NonEmptyString }),
});

const SearchResponse = Schema.Struct({
  result: Schema.Struct({
    structuredContent: Schema.Struct({
      matches: Schema.Array(Schema.Struct({ id: Schema.String })),
    }),
  }),
});

const TimeoutResponse = Schema.Struct({
  _tag: Schema.Literal("SandboxError"),
  reason: Schema.Literal("timeout"),
});

const ReadyResponse = Schema.Struct({
  level: Schema.Finite,
  levelName: Schema.String,
});

const RateDocument = Schema.Struct({
  paths: Schema.Struct({
    "/api/execute": Schema.Struct({
      post: Schema.Struct({
        responses: Schema.Record(Schema.String, Schema.Unknown),
      }),
    }),
  }),
});

const NetworkResponse = Schema.Union([
  Schema.Struct({ message: Schema.String }),
  Schema.Struct({ error: Schema.Struct({ message: Schema.String }) }),
  Schema.Struct({ result: Schema.Struct({ message: Schema.String }) }),
]);

export const measuredCheck = <E, R>(
  check: string,
  work: Effect.Effect<boolean, E, R>
) =>
  runCheck(
    check,
    Effect.gen(function* measureBehavior() {
      const passed = yield* work;

      return {
        check,
        control: 1,
        counts: { observed: 1 },
        observedAt: yield* Clock.currentTimeMillis,
        reason: passed ? "behavior-confirmed" : "behavior-mismatch",
        ...(passed
          ? { exitCode: 0, outcome: "passed", status: "green" }
          : { exitCode: 2, outcome: "failed", status: "red" }),
      } satisfies Verdict;
    })
  );

export const postDeployChecks = Effect.fn("postDeployChecks")(
  function* postDeployChecks(base: string) {
    const client = yield* HttpClient.HttpClient;
    const url = base.replace(/\/$/u, "");
    const verdicts: Verdict[] = [];

    for (const route of [
      "/",
      "/llms.txt",
      "/openapi.json",
      "/.well-known/mcp.json",
      "/.well-known/agent-skills/index.json",
    ]) {
      verdicts.push(
        yield* measuredCheck(
          `route:${route}`,
          client
            .get(`${url}${route}`)
            .pipe(Effect.map((response) => response.status === 200))
        )
      );
    }

    const post = (
      route: string,
      json: string,
      headers: Readonly<Record<string, string>> = {}
    ) =>
      client.execute(
        HttpClientRequest.post(`${url}${route}`).pipe(
          HttpClientRequest.setHeaders({
            "content-type": "application/json",
            ...headers,
          }),
          HttpClientRequest.bodyText(json, "application/json")
        )
      );

    const mcpHeaders = {
      "MCP-Protocol-Version": "2026-07-28",
      accept: "application/json, text/event-stream",
    };

    const meta = {
      "io.modelcontextprotocol/clientCapabilities": {},
      "io.modelcontextprotocol/clientInfo": {
        name: "rat-stack-checks",
        version: "0.1.0",
      },
      "io.modelcontextprotocol/protocolVersion": "2026-07-28",
    };

    verdicts.push(
      yield* measuredCheck(
        "mcp-tools-list",
        Effect.gen(function* toolsList() {
          const response = yield* post(
            "/mcp",
            JSON.stringify({
              id: "deploy-tools",
              jsonrpc: "2.0",
              method: "tools/list",
              params: { _meta: meta },
            }),
            { ...mcpHeaders, "Mcp-Method": "tools/list" }
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ToolsResponse)(response);

          return (
            response.status === 200 &&
            ["search", "read", "execute"].every((name) =>
              document.result.tools.some((tool) => tool.name === name)
            )
          );
        })
      ),
      yield* measuredCheck(
        "execute-round-trip",
        Effect.gen(function* executeRoundTrip() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({
              code: 'const found = await tools.search({ query: "learn-rat-stack", limit: 1 }); return await tools.read({ id: found.matches[0].id });',
            })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ExecuteResponse)(response);

          return (
            response.status === 200 &&
            document.result.id === "ratstack://skills/learn-rat-stack" &&
            document.result.text.trim().length > 0
          );
        })
      ),
      yield* measuredCheck(
        "sandbox-network-refused",
        Effect.gen(function* networkRefused() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({
              code: 'return await fetch("https://example.com");',
            })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(NetworkResponse)(response);

          let message = "";

          if ("message" in document) {
            ({ message } = document);
          } else if ("error" in document) {
            ({ message } = document.error);
          } else {
            ({ message } = document.result);
          }

          return message
            .toLowerCase()
            .includes("not permitted to access the internet");
        })
      ),
      yield* measuredCheck(
        "sandbox-timeout",
        Effect.gen(function* sandboxTimeout() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({ code: "while(true){}" })
          );

          yield* HttpClientResponse.schemaBodyJson(TimeoutResponse)(response);

          return true;
        })
      ),
      yield* measuredCheck(
        "mcp-search",
        Effect.gen(function* mcpSearch() {
          const response = yield* post(
            "/mcp",
            JSON.stringify({
              id: "deploy-search",
              jsonrpc: "2.0",
              method: "tools/call",
              params: {
                _meta: meta,
                arguments: { limit: 1, query: "learn-rat-stack" },
                name: "search",
              },
            }),
            { ...mcpHeaders, "Mcp-Method": "tools/call", "Mcp-Name": "search" }
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(SearchResponse)(response);

          return (
            response.status === 200 &&
            document.result.structuredContent.matches.length > 0
          );
        })
      ),
      yield* measuredCheck(
        "execute-429-document",
        Effect.gen(function* rateDocument() {
          const response = yield* client.get(`${url}/openapi.json`);

          const document =
            yield* HttpClientResponse.schemaBodyJson(RateDocument)(response);

          return (
            response.status === 200 &&
            Object.hasOwn(document.paths["/api/execute"].post.responses, "429")
          );
        })
      ),
      yield* measuredCheck(
        "agent-readiness",
        Effect.gen(function* agentReadiness() {
          const response = yield* client.execute(
            HttpClientRequest.post("https://isitagentready.com/api/scan").pipe(
              HttpClientRequest.bodyText(
                JSON.stringify({ url }),
                "application/json"
              )
            )
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ReadyResponse)(response);

          return response.status === 200 && document.level === 5;
        })
      )
    );

    return verdicts;
  },
  Effect.scoped
);

import { describe, expect, it } from "@effect/vitest";
import { Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { capturedQuery, isSensitiveKey, referrerOf } from "../src/index.js";
import { queryPairs, sensitiveWord, word } from "./arbitraries.js";

describe("request facts", () => {
  it.prop(
    "captured queries drop every sensitive key and keep every other value in order",
    { pairs: queryPairs },
    ({ pairs }) => {
      const params = new URLSearchParams(pairs);

      expect(capturedQuery(params)).toStrictEqual(
        Object.fromEntries(
          [...new Set(pairs.map(([key]) => key))].flatMap((key) =>
            isSensitiveKey(key) ? [] : [[key, params.getAll(key)]]
          )
        )
      );
    }
  );

  it.prop(
    "credentials, emails, codes, and session ids in a query never reach an event",
    {
      pairs: queryPairs,
      secret: sensitiveWord,
      value: word,
    },
    ({ pairs, secret, value }) => {
      const captured = capturedQuery(
        new URLSearchParams([...pairs, [secret, value]])
      );

      expect(Object.hasOwn(captured, secret)).toBe(false);
    }
  );

  it.prop(
    "referrers never carry a query string or fragment",
    {
      fragment: word,
      path: word,
      query: word,
      secure: Arbitrary.schema(Schema.Boolean),
    },
    ({ fragment, path, query, secure }) => {
      const origin = `${secure ? "https" : "http"}://example.test`;

      expect(referrerOf(`${origin}/${path}?q=${query}#${fragment}`)).toBe(
        `${origin}/${path}`
      );
      expect(referrerOf(path)).toBeUndefined();
    }
  );
});

import { describe, expect, it } from "@effect/vitest";
import { Effect, Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { resolveVisitor, webCryptoLayer } from "../src/index.js";
import type { IdentityMode } from "../src/index.js";

const Visit = Schema.Struct({
  device: Schema.Literals([0, 1, 2]),
  keepsCookie: Schema.Boolean,
  startsNewDay: Schema.Boolean,
});

const commands = Arbitrary.array(Arbitrary.schema(Visit), { maxLength: 30 });

const devices = [
  { ip: "203.0.113.1", userAgent: "Mozilla/5.0 rat" },
  { ip: "203.0.113.2", userAgent: "Mozilla/5.0 rat" },
  { ip: "198.51.100.9", userAgent: "curl/8" },
] as const;

const dayOf = (offset: number) =>
  `2026-10-${String(1 + offset).padStart(2, "0")}`;

const runSession = (
  mode: IdentityMode,
  steps: readonly (typeof Visit.Type)[]
) =>
  Effect.gen(function* replaySession() {
    let day = 0;
    const cookies = new Map<number, string>();
    const seen = new Map<string, string>();
    const idsByDay = new Map<number, Set<string>>();

    for (const step of steps) {
      if (step.startsNewDay) {
        day += 1;
      }

      const device = devices[step.device];
      const cookie = step.keepsCookie ? cookies.get(step.device) : undefined;

      const visitor = yield* resolveVisitor({
        cookie,
        day: dayOf(day),
        ip: device.ip,
        mode,
        salt: "model-salt",
        userAgent: device.userAgent,
      });

      if (mode === "persistent") {
        expect(visitor.issueCookie).toBe(cookie === undefined);

        if (cookie !== undefined) {
          expect(visitor.anonymousId).toBe(cookie);
        }

        cookies.set(step.device, visitor.anonymousId);
        continue;
      }

      expect(visitor.issueCookie).toBe(false);
      const key = `${day}|${device.ip}|${device.userAgent}`;
      const previous = seen.get(key);

      if (previous !== undefined) {
        expect(visitor.anonymousId).toBe(previous);
      }

      seen.set(key, visitor.anonymousId);
      const today = idsByDay.get(day) ?? new Set<string>();
      today.add(visitor.anonymousId);
      idsByDay.set(day, today);
    }

    const days = [...idsByDay.values()];

    const repeated = days.flatMap((ids, index) =>
      days
        .slice(index + 1)
        .flatMap((later) => [...ids].filter((id) => later.has(id)))
    );

    expect(repeated).toStrictEqual([]);
  }).pipe(Effect.provide(webCryptoLayer));

describe("visitor identity model", () => {
  it.effect.prop(
    "persistent ids survive every visit that keeps the cookie and are reissued when it is lost",
    { steps: commands },
    ({ steps }) => runSession("persistent", steps)
  );

  it.effect.prop(
    "daily ids are stable within a day, never set a cookie, and never repeat across days",
    { steps: commands },
    ({ steps }) => runSession("daily", steps)
  );
});

