import { Effect, Schema } from "effect";

import {
  CodeBodyWithReference,
  CodeDuplicateKey,
  CodeInvalidProps,
  CodeInvalidRanges,
  CodeMalformedMeta,
  CodeUnknownKey,
} from "./errors.ts";
import {
  CodeRequest,
  RangeSchema,
  extensions,
  normalizeCodeLanguage,
} from "./model.ts";
import type { CodeFence, Range } from "./model.ts";

type ErrorContext = Omit<
  ConstructorParameters<typeof CodeInvalidProps>[0],
  "_tag"
>;

type ContextFor = (fix: string) => ErrorContext;

const whitespace = (char: string) =>
  char === " " || char === "\t" || char === "\n" || char === "\r";

const digits = (value: string) => {
  for (let index = 0; index < value.length; index += 1) {
    const char = value.charAt(index);

    if (char < "0" || char > "9") {
      return false;
    }
  }

  return value !== "";
};

const allowedKeys = new Set(["repo", "path", "at", "lines", "title"]);

const quotedString = Schema.fromJsonString(Schema.String);

const scanValue = Effect.fn("scanValue")(function* scanValue(
  meta: string,
  start: number,
  key: string,
  context: ContextFor
) {
  let end = start;

  if (meta.charAt(start) !== '"') {
    while (end < meta.length && !whitespace(meta.charAt(end))) {
      end += 1;
    }

    return { end, value: meta.slice(start, end) };
  }

  end += 1;
  let escaped = false;

  while (end < meta.length) {
    const char = meta.charAt(end);

    if (!escaped && char === '"') {
      const value = yield* Schema.decodeEffect(quotedString)(
        meta.slice(start, end + 1)
      ).pipe(
        Effect.mapError(
          () =>
            new CodeMalformedMeta(context(`Use a valid quoted ${key} string.`))
        )
      );

      return { end: end + 1, value };
    }

    escaped = !escaped && char === "\\";
    end += 1;
  }

  return yield* new CodeMalformedMeta(
    context(`Close the quoted ${key} value.`)
  );
});

const scanPair = Effect.fn("scanPair")(function* scanPair(
  meta: string,
  start: number,
  fields: Readonly<Record<string, string>>,
  context: ContextFor
) {
  let cursor = start;

  while (
    cursor < meta.length &&
    !whitespace(meta.charAt(cursor)) &&
    meta.charAt(cursor) !== "="
  ) {
    cursor += 1;
  }

  const key = meta.slice(start, cursor);

  if (meta.charAt(cursor) !== "=") {
    return yield* new CodeMalformedMeta(
      context('Write metadata as key=value or key="quoted value".')
    );
  }

  if (!allowedKeys.has(key)) {
    return yield* new CodeUnknownKey(
      context(`Unknown key ${key}; use repo, path, at, lines or title.`)
    );
  }

  if (Object.hasOwn(fields, key)) {
    return yield* new CodeDuplicateKey(context(`Remove duplicate ${key}.`));
  }

  const { end, value } = yield* scanValue(meta, cursor + 1, key, context);

  if (value === "" || (end < meta.length && !whitespace(meta.charAt(end)))) {
    return yield* new CodeMalformedMeta(
      context(
        `Give ${key} a value and separate metadata items with whitespace.`
      )
    );
  }

  return { end, key, value };
});

const parseRanges = Effect.fn("parseRanges")(function* parseRanges(
  value: string,
  label: string,
  context: ContextFor
): Effect.fn.Return<readonly Range[], CodeInvalidRanges> {
  if (value === "") {
    return [];
  }

  const ranges: Range[] = [];

  for (const part of value.split(",")) {
    const pair = part.split("-");
    const start = Number(pair[0]);
    const end = Number(pair[1] ?? pair[0]);

    const parsed = yield* Schema.decodeEffect(RangeSchema)({ end, start }).pipe(
      Effect.mapError(
        () =>
          new CodeInvalidRanges(
            context(
              `Use positive line numbers or ranges for ${label}, such as 3,5-7.`
            )
          )
      )
    );

    if (
      pair.length > 2 ||
      !pair.every(digits) ||
      end < start ||
      (ranges.at(-1)?.end ?? 0) >= start
    ) {
      return yield* new CodeInvalidRanges(
        context(`Order ${label} without overlaps, such as 3,5-7.`)
      );
    }

    ranges.push(parsed);
  }

  return ranges;
});

const validCommit = (value: string) => {
  for (let index = 0; index < value.length; index += 1) {
    const char = value.charAt(index);

    if (!(char >= "0" && char <= "9") && !(char >= "a" && char <= "f")) {
      return false;
    }
  }

  return value.length === 40;
};

const validPath = (value: string) =>
  !value.startsWith("/") &&
  !value.includes(":") &&
  !value
    .split("/")
    .some((part) => part === ".." || part === "" || part === ".");

const validateReference = Effect.fn("validateReference")(
  function* validateReference(
    fields: Readonly<Record<string, string>>,
    body: string,
    context: ContextFor
  ) {
    if (fields.path === undefined) {
      if (["repo", "at", "lines"].some((key) => fields[key] !== undefined)) {
        return yield* new CodeInvalidProps(
          context("Add path for a pinned reference, or remove repo/at/lines.")
        );
      }

      return false;
    }

    if (body.trim() !== "") {
      return yield* new CodeBodyWithReference(
        context(
          "Remove the fence body; path references read their content from Git."
        )
      );
    }

    if (!validCommit(fields.at ?? "")) {
      return yield* new CodeInvalidProps(
        context("Pin at to a full 40-character lowercase commit SHA.")
      );
    }

    if (!validPath(fields.path)) {
      return yield* new CodeInvalidProps(
        context(
          "Use a repository-relative file path without traversal or colons."
        )
      );
    }

    return true;
  }
);

const scannedRequest = Effect.fn("scannedRequest")(function* scannedRequest(
  node: CodeFence,
  sourcePath: string,
  fields: Readonly<Record<string, string>>,
  highlightText: string | undefined,
  configured: boolean,
  language: string,
  context: ContextFor
) {
  const reference = yield* validateReference(fields, node.value, context);
  const ranges = yield* parseRanges(fields.lines ?? "", "lines", context);

  if (reference && ranges.length === 0) {
    return yield* new CodeInvalidRanges(
      context("Set lines to the excerpt, such as lines=3-7.")
    );
  }

  if (highlightText === "") {
    return yield* new CodeMalformedMeta(
      context("Put line numbers inside the highlight set, such as {3,5-7}.")
    );
  }

  const highlights = yield* parseRanges(
    highlightText ?? "",
    "highlights",
    context
  ).pipe(Effect.mapError((error) => new CodeMalformedMeta(context(error.fix))));

  const selectedLanguage =
    language === ""
      ? (extensions.get(fields.path?.split(".").at(-1) ?? "") ?? "markdown")
      : normalizeCodeLanguage(language);

  return yield* Schema.decodeEffect(CodeRequest)({
    body: node.value,
    commit: fields.at ?? "<inline>",
    configured,
    highlights,
    language: selectedLanguage,
    line: node.line,
    path: fields.path ?? "<inline>",
    rangeText: fields.lines ?? "all",
    ranges,
    reference,
    repo: fields.repo ?? "rat-stack",
    sourcePath,
    title: fields.title ?? fields.path?.split("/").at(-1) ?? "Code",
  }).pipe(
    Effect.mapError(
      () =>
        new CodeInvalidProps(
          context("Use the documented fence metadata grammar.")
        )
    )
  );
});

export const parseCodeRequest = Effect.fn("parseCodeRequest")(
  function* parseCodeRequest(node: CodeFence, sourcePath: string) {
    const rawLanguage = node.lang ?? "";

    const hasLanguage =
      rawLanguage !== "" &&
      !rawLanguage.includes("=") &&
      !rawLanguage.startsWith("{");

    const meta = [hasLanguage ? "" : rawLanguage, node.meta ?? ""]
      .filter((part) => part !== "")
      .join(" ");

    const fields: Record<string, string> = {};
    let highlightText: string | undefined;
    let cursor = 0;

    const context: ContextFor = (fix) => ({
      actualLength: null,
      commit: fields.at ?? "<inline>",
      fix,
      line: node.line,
      path: fields.path ?? "<inline>",
      ranges: fields.lines ?? "all",
      repo: fields.repo ?? "rat-stack",
      sourcePath,
    });

    while (cursor < meta.length) {
      if (whitespace(meta.charAt(cursor))) {
        cursor += 1;
        continue;
      }

      if (meta.charAt(cursor) === "{") {
        if (highlightText !== undefined) {
          return yield* new CodeDuplicateKey(
            context("Use one {line,ranges} highlight set.")
          );
        }

        const end = meta.indexOf("}", cursor + 1);

        if (end === -1) {
          return yield* new CodeMalformedMeta(
            context("Close the highlight set with }.")
          );
        }

        highlightText = meta.slice(cursor + 1, end);
        cursor = end + 1;

        if (cursor < meta.length && !whitespace(meta.charAt(cursor))) {
          return yield* new CodeMalformedMeta(
            context("Separate metadata items with whitespace.")
          );
        }
      } else {
        const item = yield* scanPair(meta, cursor, fields, context);
        fields[item.key] = item.value;
        cursor = item.end;
      }
    }

    return yield* scannedRequest(
      node,
      sourcePath,
      fields,
      highlightText,
      meta !== "",
      hasLanguage ? rawLanguage : "",
      context
    );
  }
);

export const printCodeRequest = (request: CodeRequest): CodeFence => {
  const lines =
    request.rangeText === "all"
      ? ""
      : `lines=${JSON.stringify(request.rangeText)} `;

  const fields = request.reference
    ? `repo=${JSON.stringify(request.repo)} path=${JSON.stringify(request.path)} at=${request.commit} ${lines}`
    : "";

  const highlights =
    request.highlights.length === 0
      ? ""
      : `{${request.highlights.map((range) => (range.start === range.end ? String(range.start) : `${range.start}-${range.end}`)).join(",")}} `;

  return {
    lang: request.language,
    line: request.line,
    meta: request.configured
      ? `${fields}${highlights}title=${JSON.stringify(request.title)}`
      : null,
    value: request.body,
  };
};

import {
  Context,
  Crypto,
  DateTime,
  Effect,
  Layer,
  Option,
  Schema,
} from "effect";

import { AbuseScore } from "./abuse-score.js";
import { ContactRefSchema, IntakeEvents } from "./intake-events.js";
import type {
  IntakeObject,
  IntakeStatement,
  IntakeVerb,
} from "./intake-events.js";
import { IntakeTicket } from "./intake-ticket.js";
import { normalizeAddress } from "./interest-address.js";
import { SubscriberIntake } from "./interest-intake.js";
import { normalizeClientIp } from "./interest-ip.js";
import { InterestTokens } from "./interest-token.js";
import { JoinContactStore } from "./join-contact-store.js";
import { runJoinDelivery } from "./join-delivery-machine.js";
import { JOIN_ANSWER, JOIN_NOT_OPEN } from "./join-interest-contract.js";
import type { JoinInput, JoinOutput } from "./join-interest-contract.js";
import { JoinInterest, newStatusRef } from "./join-interest-port.js";

type IdentityStatement = {
  -readonly [Key in "name" | "x"]?: Exclude<JoinInput[Key], undefined>;
};

export const JoinRequest = Context.Reference<{
  readonly ip: string | undefined;
  readonly userAgent: string;
  readonly allow: (agentRef: string) => Effect.Effect<boolean>;
}>("@rat-stack/core/JoinRequest", {
  defaultValue: () => ({
    allow: () => Effect.succeed(false),
    ip: undefined,
    userAgent: "",
  }),
});

export const joinIntakeLayer = Layer.effect(
  JoinInterest,
  Effect.gen(function* makeJoinIntake() {
    const tickets = yield* IntakeTicket;
    const scorer = yield* AbuseScore;
    const events = yield* IntakeEvents;
    const contacts = yield* JoinContactStore;
    const intake = yield* SubscriberIntake;
    const tokens = yield* InterestTokens;
    const crypto = yield* Crypto.Crypto;

    const submit = Effect.fn("JoinInterest.submit")(function* submit(
      input: JoinInput
    ): Effect.fn.Return<JoinOutput> {
      const statusRef = yield* newStatusRef;
      const answer = { message: JOIN_ANSWER, statusRef } as const;

      if (intake.agent?.enabled !== true) {
        return { message: JOIN_NOT_OPEN, statusRef };
      }

      return yield* Effect.gen(function* processSubmission() {
        const request = yield* JoinRequest;

        if (!(yield* request.allow(input.agentRef))) {
          return answer;
        }

        const ip = normalizeClientIp(request.ip);
        const address = normalizeAddress(input.email);

        if (Option.isNone(ip) || Option.isNone(address)) {
          return answer;
        }

        const ticket = yield* tickets.verify(input.ticket, statusRef);

        const clientBucket = {
          ipHash: yield* tokens.digest("ip", ip.value),
          uaHash: yield* tokens.digest("ua", request.userAgent),
        };

        const verdict = yield* scorer.score({
          agentRef: input.agentRef,
          answers: input.answers ?? {},
          clientBucket,
          ticket,
        });

        const contactRef = yield* crypto.randomUUIDv4.pipe(
          Effect.flatMap(Schema.decodeEffect(ContactRefSchema)),
          Effect.orDie
        );

        yield* contacts.save({
          agentRef: input.agentRef,
          clientBucket,
          contactRef,
          email: address.value,
          hold: verdict.hold,
          score: verdict.score,
          signals: verdict.signals,
          state: "held",
          submissionId: statusRef,
          ticket: input.ticket,
        });
        const timestamp = DateTime.formatIso(yield* DateTime.now);

        const statement = Effect.fn("JoinInterest.statement")(
          function* statement(
            verb: IntakeVerb,
            object: IntakeObject,
            result?: Schema.Json
          ): Effect.fn.Return<IntakeStatement> {
            const recorded: IntakeStatement = {
              actor: contactRef,
              context: { intake: "tokenmaxx", submissionId: statusRef },
              id: yield* crypto.randomUUIDv7.pipe(Effect.orDie),
              object,
              timestamp,
              verb,
            };

            return result === undefined ? recorded : { ...recorded, result };
          }
        );

        const identity: IdentityStatement = {};

        if (input.name !== undefined) {
          identity.name = input.name;
        }

        if (input.x !== undefined) {
          identity.x = input.x;
        }

        const statements: IntakeStatement[] = [
          yield* statement("started", "tokenmaxx/intake", identity),
        ];

        for (const question of ["building", "today", "leaveWith"] as const) {
          const value = input.answers?.[question];

          if (value !== undefined) {
            statements.push(
              yield* statement(
                "answered",
                `tokenmaxx/questions/${question}`,
                value
              )
            );
          }
        }

        statements.push(
          yield* statement("consented", "tokenmaxx/consents/contact", true),
          yield* statement(
            "consented",
            "tokenmaxx/consents/share",
            input.consent.share ?? false
          ),
          yield* statement("submitted", "tokenmaxx/intake", {
            held: verdict.hold,
            score: verdict.score,
            signals: [...verdict.signals],
          })
        );
        yield* events.record(statements);

        if (verdict.hold) {
          return answer;
        }

        yield* contacts.setState(statusRef, "ready");

        const result = yield* runJoinDelivery({ submissionId: statusRef }).pipe(
          Effect.provideService(SubscriberIntake, intake),
          Effect.provideService(JoinContactStore, contacts)
        );

        const stateFor = {
          accepted: "accepted",
          refused: "refused",
          retry: "ready",
        } as const;

        yield* contacts.setState(statusRef, stateFor[result.kind]);

        return answer;
      }).pipe(Effect.catchCause(() => Effect.succeed(answer)));
    });

    return { submit };
  })
);

