import { expect, it } from "@effect/vitest";
import { Cause, Deferred, Effect, Exit, Fiber, Ref, Result } from "effect";

it.effect.each(["success", "failure", "interruption"])(
  "closes an acquired resource exactly once after %s",
  (outcome) =>
    Effect.gen(function* resourceExit() {
      const acquired = yield* Ref.make(0);
      const released = yield* Ref.make(0);
      const started = yield* Deferred.make<boolean>();

      const acquire = Effect.acquireRelease(
        Effect.sync(() => ({ name: "counted-resource" })).pipe(
          Effect.tap(() => Ref.update(acquired, (count) => count + 1)),
          Effect.tap(() => Deferred.succeed(started, true))
        ),
        () => Ref.update(released, (count) => count + 1)
      );

      const use = Effect.scoped(
        Effect.gen(function* useResource() {
          const resource = yield* acquire;
          expect(resource.name).toBe("counted-resource");

          if (outcome === "failure") {
            return yield* Effect.fail("expected-refusal");
          }

          if (outcome === "interruption") {
            return yield* Effect.never;
          }

          return resource.name;
        })
      );

      if (outcome === "interruption") {
        const fiber = yield* Effect.forkChild(use);
        yield* Deferred.await(started);
        yield* Fiber.interrupt(fiber);
        const exit = yield* Fiber.await(fiber);
        expect(Exit.isFailure(exit) && Cause.hasInterrupts(exit.cause)).toBe(
          true
        );
      } else {
        const result = yield* Effect.result(use);
        expect(Result.isFailure(result)).toBe(outcome === "failure");

        if (Result.isFailure(result)) {
          expect(result.failure).toBe("expected-refusal");
        }
      }

      expect(yield* Ref.get(acquired)).toBe(1);
      expect(yield* Ref.get(released)).toBe(1);
    })
);

import { expect, it } from "@effect/vitest";
import { Effect, Layer, Predicate, Ref, Schema } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";
import { OtlpSerialization, OtlpTracer } from "effect/observability";

const ExportedTrace = Schema.Struct({
  resourceSpans: Schema.Array(
    Schema.Struct({
      scopeSpans: Schema.Array(
        Schema.Struct({
          spans: Schema.Array(
            Schema.Struct({
              attributes: Schema.Array(
                Schema.Struct({ key: Schema.String, value: Schema.Unknown })
              ),
              name: Schema.String,
            })
          ),
        })
      ),
    })
  ),
});

it.effect(
  "scope shutdown exports named spans through the supplied transport",
  () =>
    Effect.gen(function* traceDelivery() {
      const deliveries = yield* Ref.make<
        readonly (typeof ExportedTrace.Type)[]
      >([]);

      const client = HttpClient.make((request) =>
        Effect.gen(function* receiveTelemetry() {
          if (!Predicate.isTagged(request.body, "Uint8Array")) {
            return yield* Effect.die("Expected serialized OTLP JSON bytes");
          }

          const text = new TextDecoder().decode(request.body.body);

          const trace = yield* Schema.decodeEffect(
            Schema.fromJsonString(ExportedTrace)
          )(text).pipe(Effect.orDie);

          yield* Ref.update(deliveries, (received) => [...received, trace]);

          return HttpClientResponse.fromWeb(request, new Response());
        })
      );

      const tracing = OtlpTracer.layer({
        resource: { serviceName: "wiki-fixture" },
        url: "https://collector.example.test/v1/traces",
      }).pipe(
        Layer.provide(OtlpSerialization.layerJson),
        Layer.provide(Layer.succeed(HttpClient.HttpClient, client))
      );

      yield* Effect.scoped(
        Effect.void.pipe(
          Effect.withSpan("fixture.read"),
          Effect.annotateSpans({ phase: "read" }),
          Effect.provide(tracing)
        )
      );

      const spans = (yield* Ref.get(deliveries)).flatMap((delivery) =>
        delivery.resourceSpans.flatMap((resource) =>
          resource.scopeSpans.flatMap((scope) => scope.spans)
        )
      );

      expect(spans.map((span) => span.name)).toContain("fixture.read");
      expect(
        spans.flatMap((span) =>
          span.attributes.map((attribute) => attribute.key)
        )
      ).toContain("phase");
    })
);

import { Action } from "alchemy";
import type { Input } from "alchemy";
import { CurrentRuntimeContext, sanitizeKey } from "alchemy/RuntimeContext";
import {
  connectionSourceDigest,
  resolveConnectionSource,
} from "alchemy/SQL/ConnectionSource";
import type { StaticConnectionSource } from "alchemy/SQL/ConnectionSource";
import type { SqlExecutor } from "alchemy/SQL/Migrations/Format";
import { makePgMigrationExecutor } from "alchemy/SQL/Migrations/PgExecutor";
import {
  normalizeMigrationsInput,
  runMigrations,
} from "alchemy/SQL/Migrations/Registry";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Schema from "effect/Schema";

class PostgresMigrationConnectionError extends Schema.TaggedError<PostgresMigrationConnectionError>()(
  "PostgresMigrationConnectionError",
  { cause: Schema.Defect() }
) {}

interface MigrationInput {
  readonly databaseId: string;
  readonly directory: string;
  readonly schemaHash: string;
  readonly sourceDigest: string;
}

export const runPostgresMigrations = (
  directory: string,
  executor: SqlExecutor
) =>
  runMigrations({
    input: normalizeMigrationsInput(directory),
    stamped: {},
    withExecutor: (apply) => apply(executor),
  });

export const registerPostgresMigrations = (options: {
  readonly id: string;
  readonly databaseId: Input<string>;
  readonly directory: string;
  readonly schemaHash: Input<string>;
  readonly source: StaticConnectionSource;
}) =>
  Effect.gen(function* registerMigrations() {
    const Migrate = Action(
      "Database.PostgresMigrate",
      Effect.gen(function* makeRunner() {
        const connectionUrl = yield* resolveConnectionSource(options.source);

        return (input: MigrationInput) =>
          Effect.scoped(
            Effect.gen(function* applyMigrations() {
              const url = Redacted.value(yield* connectionUrl);

              const { Client } = yield* Effect.promise(
                // oxlint-disable-next-line promise-function-async -- Effect.promise consumes a Promise factory directly.
                () => import("pg")
              );

              return yield* Effect.acquireUseRelease(
                Effect.tryPromise({
                  catch: (cause) =>
                    new PostgresMigrationConnectionError({ cause }),
                  // @effect-diagnostics-next-line asyncFunction:off -- The pg client exposes Promise-based connection setup.
                  try: async () => {
                    const connection = new Client({ connectionString: url });

                    await connection.connect();

                    return connection;
                  },
                }),
                (connection) =>
                  runPostgresMigrations(
                    input.directory,
                    makePgMigrationExecutor(connection)
                  ),
                (connection) =>
                  Effect.tryPromise({
                    catch: (cause) =>
                      new PostgresMigrationConnectionError({ cause }),
                    // @effect-diagnostics-next-line asyncFunction:off -- The pg client exposes Promise-based shutdown.
                    try: async () => {
                      await connection.end();
                    },
                  }).pipe(Effect.orDie)
              );
            })
          );
      })
    );

    const result = yield* Migrate(`${options.id}-postgres-migrations`, {
      databaseId: options.databaseId,
      directory: options.directory,
      schemaHash: options.schemaHash,
      sourceDigest: connectionSourceDigest(options.source),
    });

    const runtimeContext = yield* CurrentRuntimeContext;

    if (runtimeContext !== undefined) {
      yield* runtimeContext.set(
        sanitizeKey(`${options.id}PostgresMigrations`),
        result
      );
    }
  });

import { gateOutcome, runCheck } from "@rat-stack/check-harness";
import type { Verdict } from "@rat-stack/check-harness";
import { Clock, DateTime, Effect, Option, Schema } from "effect";
import * as HttpClient from "effect/http/HttpClient";
import * as HttpClientRequest from "effect/http/HttpClientRequest";
import * as HttpClientResponse from "effect/http/HttpClientResponse";

const ToolsResponse = Schema.Struct({
  result: Schema.Struct({
    tools: Schema.Array(Schema.Struct({ name: Schema.String })),
  }),
});

const ExecuteResponse = Schema.Struct({
  result: Schema.Struct({ id: Schema.String, text: Schema.NonEmptyString }),
});

const SearchResponse = Schema.Struct({
  result: Schema.Struct({
    structuredContent: Schema.Struct({
      matches: Schema.Array(Schema.Struct({ id: Schema.String })),
    }),
  }),
});

const TimeoutResponse = Schema.TaggedStruct("SandboxError", {
  reason: Schema.Literal("timeout"),
});

const ReadyResponse = Schema.Struct({
  cacheHit: Schema.optionalKey(Schema.Boolean),
  cached: Schema.optionalKey(Schema.Boolean),
  level: Schema.optionalKey(Schema.Finite),
  levelName: Schema.optionalKey(Schema.String),
  scannedAt: Schema.optionalKey(Schema.String),
  siteError: Schema.optionalKey(Schema.Struct({ httpStatus: Schema.Finite })),
});

interface ReadinessObservation {
  readonly document: typeof ReadyResponse.Type;
  readonly status: number;
}

const RateDocument = Schema.Struct({
  paths: Schema.Struct({
    "/api/execute": Schema.Struct({
      post: Schema.Struct({
        responses: Schema.Record(Schema.String, Schema.Unknown),
      }),
    }),
  }),
});

const NetworkResponse = Schema.Union([
  Schema.Struct({ message: Schema.String }),
  Schema.Struct({ error: Schema.Struct({ message: Schema.String }) }),
  Schema.Struct({ result: Schema.Struct({ message: Schema.String }) }),
]);

export const measuredCheck = <E, R>(
  check: string,
  work: Effect.Effect<boolean, E, R>
) =>
  runCheck(
    check,
    Effect.gen(function* measureBehavior() {
      const passed = yield* work;

      return {
        check,
        control: 1,
        counts: { observed: 1 },
        observedAt: yield* Clock.currentTimeMillis,
        reason: passed ? "behavior-confirmed" : "behavior-mismatch",
        ...(passed
          ? { exitCode: 0, outcome: "passed", status: "green" }
          : { exitCode: 2, outcome: "failed", status: "red" }),
      } satisfies Verdict;
    })
  );

export const settledReadinessCheck = Effect.fn("settledReadinessCheck")(
  function* settledReadinessCheck<E, R>(
    work: Effect.Effect<ReadinessObservation, E, R>,
    appliedAt: number
  ) {
    const attempts: Verdict[] = [];

    for (let attempt = 0; attempt < 2; attempt += 1) {
      const startedAt = yield* Clock.currentTimeMillis;

      const verdict = yield* runCheck(
        "agent-readiness",
        Effect.gen(function* observeReadiness() {
          const { document, status } = yield* work;

          const scanned =
            document.scannedAt === undefined
              ? Option.none()
              : DateTime.make(document.scannedAt);

          const fresh =
            Option.isSome(scanned) &&
            DateTime.toEpochMillis(scanned.value) >= appliedAt;

          const siteFailed = document.siteError !== undefined;

          const evidence = {
            check: "agent-readiness",
            counts: { observed: 1 },
            observedAt: yield* Clock.currentTimeMillis,
            provenance: [
              {
                fetchedAt: yield* Clock.currentTimeMillis,
                id: `agent-readiness:${attempt + 1}`,
                source: "https://isitagentready.com/api/scan",
                status: `http=${status};scan=${document.scannedAt ?? "missing"};cached=${document.cached ?? "unknown"};cacheHit=${document.cacheHit ?? "unknown"};siteHttp=${document.siteError?.httpStatus ?? "none"}`,
              },
            ],
          };

          if (!siteFailed && !fresh) {
            return {
              ...evidence,
              control: 0,
              exitCode: 3,
              outcome: "errored",
              reason: "readiness-scan-freshness-unverified",
              status: "hold",
            } satisfies Verdict;
          }

          const passed = status === 200 && !siteFailed && document.level === 5;

          const failureReason = siteFailed
            ? "scanner-reported-site-error"
            : "behavior-mismatch";

          return {
            ...evidence,
            control: 1,
            reason: passed ? "behavior-confirmed" : failureReason,
            ...(passed
              ? { exitCode: 0, outcome: "passed", status: "green" }
              : { exitCode: 2, outcome: "failed", status: "red" }),
          } satisfies Verdict;
        })
      );

      const durationMs = (yield* Clock.currentTimeMillis) - startedAt;
      attempts.push({ ...verdict, counts: { ...verdict.counts, durationMs } });

      if (gateOutcome(verdict) === "pass" || attempt === 1) {
        return {
          ...verdict,
          counts: {
            ...verdict.counts,
            attempts: attempts.length,
            failedAttempts: attempts.filter(
              (row) => gateOutcome(row) !== "pass"
            ).length,
          },
          provenance: attempts.flatMap((row, index) => [
            {
              fetchedAt: row.observedAt,
              id: `attempt:${index + 1}`,
              source: "https://isitagentready.com/api/scan",
              status: `${row.status}:${row.reason}:durationMs=${row.counts.durationMs}`,
            },
            ...(row.provenance ?? []),
          ]),
        } satisfies Verdict;
      }
    }

    return yield* Effect.die("readiness-attempts-exhausted-without-verdict");
  }
);

export const contentVersionCheck = Effect.fn("contentVersionCheck")(
  function* contentVersionCheck(
    base: string,
    route: string,
    generation: string
  ) {
    const client = yield* HttpClient.HttpClient;
    const observedAt = yield* Clock.currentTimeMillis;
    const url = `${base}${route}?__rat_version=${encodeURIComponent(generation)}&__rat_probe=${observedAt}`;

    return yield* runCheck(
      `content-version:${route}`,
      Effect.gen(function* observeContentVersion() {
        const response = yield* client.execute(
          HttpClientRequest.get(url).pipe(
            HttpClientRequest.setHeaders({
              accept: "text/markdown",
              "accept-encoding": "identity",
            })
          )
        );

        const { etag } = response.headers;

        const evidence = {
          check: `content-version:${route}`,
          counts: { observed: 1 },
          deploymentVersion: generation,
          observedAt,
          provenance: [
            {
              fetchedAt: observedAt,
              id: route,
              source: url,
              status: `http=${response.status};etag=${etag ?? "missing"}`,
            },
          ],
        };

        if (etag === undefined || etag.trim().length === 0) {
          return {
            ...evidence,
            control: 0,
            exitCode: 3,
            outcome: "errored",
            reason: "content-version-header-missing",
            status: "hold",
          } satisfies Verdict;
        }

        const passed =
          response.status === 200 &&
          etag.replace(/^W\//u, "") ===
            `"${generation}:default:${encodeURIComponent(route)}"`;

        return {
          ...evidence,
          control: 1,
          reason: passed
            ? "content-version-confirmed"
            : "content-version-mismatch",
          resourceVersion: etag,
          ...(passed
            ? { exitCode: 0, outcome: "passed", status: "green" }
            : { exitCode: 2, outcome: "failed", status: "red" }),
        } satisfies Verdict;
      })
    );
  }
);

export const postDeployChecks = Effect.fn("postDeployChecks")(
  function* postDeployChecks(
    base: string,
    contentGeneration: string,
    appliedAt: number
  ) {
    const client = yield* HttpClient.HttpClient;
    const url = base.replace(/\/$/u, "");

    const verdicts: Verdict[] = [
      yield* contentVersionCheck(url, "/", contentGeneration),
      yield* contentVersionCheck(url, "/index.md", contentGeneration),
    ];

    for (const route of [
      "/",
      "/llms.txt",
      "/openapi.json",
      "/.well-known/mcp.json",
      "/.well-known/agent-skills/index.json",
    ]) {
      verdicts.push(
        yield* measuredCheck(
          `route:${route}`,
          client
            .get(`${url}${route}`)
            .pipe(Effect.map((response) => response.status === 200))
        )
      );
    }

    const post = (
      route: string,
      json: string,
      headers: Readonly<Record<string, string>> = {}
    ) =>
      client.execute(
        HttpClientRequest.post(`${url}${route}`).pipe(
          HttpClientRequest.setHeaders({
            "content-type": "application/json",
            ...headers,
          }),
          HttpClientRequest.bodyText(json, "application/json")
        )
      );

    const mcpHeaders = {
      "MCP-Protocol-Version": "2026-07-28",
      accept: "application/json, text/event-stream",
    };

    const meta = {
      "io.modelcontextprotocol/clientCapabilities": {},
      "io.modelcontextprotocol/clientInfo": {
        name: "rat-stack-checks",
        version: "0.1.0",
      },
      "io.modelcontextprotocol/protocolVersion": "2026-07-28",
    };

    verdicts.push(
      yield* measuredCheck(
        "mcp-tools-list",
        Effect.gen(function* toolsList() {
          const response = yield* post(
            "/mcp",
            JSON.stringify({
              id: "deploy-tools",
              jsonrpc: "2.0",
              method: "tools/list",
              params: { _meta: meta },
            }),
            { ...mcpHeaders, "Mcp-Method": "tools/list" }
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ToolsResponse)(response);

          return (
            response.status === 200 &&
            ["search", "read", "execute"].every((name) =>
              document.result.tools.some((tool) => tool.name === name)
            )
          );
        })
      ),
      yield* measuredCheck(
        "execute-round-trip",
        Effect.gen(function* executeRoundTrip() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({
              code: 'const found = await tools.search({ query: "learn-rat-stack", limit: 1 }); return await tools.read({ id: found.matches[0].id });',
            })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ExecuteResponse)(response);

          return (
            response.status === 200 &&
            document.result.id === "ratstack://skills/learn-rat-stack" &&
            document.result.text.trim().length > 0
          );
        })
      ),
      yield* measuredCheck(
        "sandbox-network-refused",
        Effect.gen(function* networkRefused() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({
              code: 'return await fetch("https://example.com");',
            })
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(NetworkResponse)(response);

          let message = "";

          if ("message" in document) {
            ({ message } = document);
          } else if ("error" in document) {
            ({ message } = document.error);
          } else {
            ({ message } = document.result);
          }

          return message
            .toLowerCase()
            .includes("not permitted to access the internet");
        })
      ),
      yield* measuredCheck(
        "sandbox-timeout",
        Effect.gen(function* sandboxTimeout() {
          const response = yield* post(
            "/api/execute",
            JSON.stringify({ code: "while(true){}" })
          );

          yield* HttpClientResponse.schemaBodyJson(TimeoutResponse)(response);

          return true;
        })
      ),
      yield* measuredCheck(
        "mcp-search",
        Effect.gen(function* mcpSearch() {
          const response = yield* post(
            "/mcp",
            JSON.stringify({
              id: "deploy-search",
              jsonrpc: "2.0",
              method: "tools/call",
              params: {
                _meta: meta,
                arguments: { limit: 1, query: "learn-rat-stack" },
                name: "search",
              },
            }),
            { ...mcpHeaders, "Mcp-Method": "tools/call", "Mcp-Name": "search" }
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(SearchResponse)(response);

          return (
            response.status === 200 &&
            document.result.structuredContent.matches.length > 0
          );
        })
      ),
      yield* measuredCheck(
        "execute-429-document",
        Effect.gen(function* rateDocument() {
          const response = yield* client.get(`${url}/openapi.json`);

          const document =
            yield* HttpClientResponse.schemaBodyJson(RateDocument)(response);

          return (
            response.status === 200 &&
            Object.hasOwn(document.paths["/api/execute"].post.responses, "429")
          );
        })
      ),
      yield* settledReadinessCheck(
        Effect.gen(function* agentReadiness() {
          const response = yield* client.execute(
            HttpClientRequest.post("https://isitagentready.com/api/scan").pipe(
              HttpClientRequest.bodyText(
                JSON.stringify({ url }),
                "application/json"
              )
            )
          );

          const document =
            yield* HttpClientResponse.schemaBodyJson(ReadyResponse)(response);

          return { document, status: response.status };
        }),
        appliedAt
      )
    );

    return verdicts;
  },
  Effect.scoped
);

import { Effect, Schema } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";

const Reply = Schema.Struct({ version: Schema.Int });

export class ResponseFixtureError extends Schema.TaggedError<ResponseFixtureError>()(
  "ResponseFixtureError",
  { cause: Schema.Defect(), phase: Schema.Literals(["status", "body"]) }
) {}

export const readValidatedResponse = Effect.fn("readValidatedResponse")(
  function* readValidatedResponse() {
    const client = (yield* HttpClient.HttpClient).pipe(
      HttpClient.filterStatusOk
    );

    const response = yield* client
      .get("https://provider.example.test/version")
      .pipe(
        Effect.mapError(
          (cause) => new ResponseFixtureError({ cause, phase: "status" })
        )
      );

    return yield* HttpClientResponse.schemaBodyJson(Reply)(response).pipe(
      Effect.mapError(
        (cause) => new ResponseFixtureError({ cause, phase: "body" })
      )
    );
  }
);

import { expect, it } from "@effect/vitest";
import { Effect, Result } from "effect";
import { HttpClient, HttpClientResponse } from "effect/http";

import { readValidatedResponse } from "./fixtures/validated-http-response.js";

it.effect.each([
  { body: '{"version":4}', expected: "success", status: 200 },
  { body: '{"version":4}', expected: "status", status: 503 },
  { body: "{", expected: "body", status: 200 },
  { body: '{"version":"four"}', expected: "body", status: 200 },
])("checks status and decoded shape: $expected ($status, $body)", (scenario) =>
  Effect.gen(function* validateResponse() {
    const client = HttpClient.make((request) =>
      Effect.sync(() =>
        HttpClientResponse.fromWeb(
          request,
          new Response(scenario.body, {
            headers: { "content-type": "application/json" },
            status: scenario.status,
          })
        )
      )
    );

    const result = yield* readValidatedResponse().pipe(
      Effect.provideService(HttpClient.HttpClient, client),
      Effect.result
    );

    if (Result.isFailure(result)) {
      expect(result.failure._tag).toBe("ResponseFixtureError");
      expect(result.failure.phase).toBe(scenario.expected);
    } else {
      expect(scenario.expected).toBe("success");
      expect(result.success.version).toBe(4);
    }
  })
);

import { describe, expect, it } from "@effect/vitest";
import { Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { capturedQuery, isSensitiveKey, referrerOf } from "../src/index.js";
import { queryPairs, sensitiveWord, word } from "./arbitraries.js";

describe("request facts", () => {
  it.prop(
    "captured queries drop every sensitive key and keep every other value in order",
    { pairs: queryPairs },
    ({ pairs }) => {
      const params = new URLSearchParams(pairs);

      expect(capturedQuery(params)).toStrictEqual(
        Object.fromEntries(
          [...new Set(pairs.map(([key]) => key))].flatMap((key) =>
            isSensitiveKey(key) ? [] : [[key, params.getAll(key)]]
          )
        )
      );
    }
  );

  it.prop(
    "credentials, emails, codes, and session ids in a query never reach an event",
    {
      pairs: queryPairs,
      secret: sensitiveWord,
      value: word,
    },
    ({ pairs, secret, value }) => {
      const captured = capturedQuery(
        new URLSearchParams([...pairs, [secret, value]])
      );

      expect(Object.hasOwn(captured, secret)).toBe(false);
    }
  );

  it.prop(
    "referrers never carry a query string or fragment",
    {
      fragment: word,
      path: word,
      query: word,
      secure: Arbitrary.schema(Schema.Boolean),
    },
    ({ fragment, path, query, secure }) => {
      const origin = `${secure ? "https" : "http"}://example.test`;

      expect(referrerOf(`${origin}/${path}?q=${query}#${fragment}`)).toBe(
        `${origin}/${path}`
      );
      expect(referrerOf(path)).toBeUndefined();
    }
  );
});

import { describe, expect, it } from "@effect/vitest";
import { Effect, Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { resolveVisitor, webCryptoLayer } from "../src/index.js";
import type { IdentityMode } from "../src/index.js";

const Visit = Schema.Struct({
  device: Schema.Literals([0, 1, 2]),
  keepsCookie: Schema.Boolean,
  startsNewDay: Schema.Boolean,
});

const commands = Arbitrary.array(Arbitrary.schema(Visit), { maxLength: 30 });

const devices = [
  { ip: "203.0.113.1", userAgent: "Mozilla/5.0 rat" },
  { ip: "203.0.113.2", userAgent: "Mozilla/5.0 rat" },
  { ip: "198.51.100.9", userAgent: "curl/8" },
] as const;

const dayOf = (offset: number) =>
  `2026-10-${String(1 + offset).padStart(2, "0")}`;

const runSession = (
  mode: IdentityMode,
  steps: readonly (typeof Visit.Type)[]
) =>
  Effect.gen(function* replaySession() {
    let day = 0;
    const cookies = new Map<number, string>();
    const seen = new Map<string, string>();
    const idsByDay = new Map<number, Set<string>>();

    for (const step of steps) {
      if (step.startsNewDay) {
        day += 1;
      }

      const device = devices[step.device];
      const cookie = step.keepsCookie ? cookies.get(step.device) : undefined;

      const visitor = yield* resolveVisitor({
        cookie,
        day: dayOf(day),
        ip: device.ip,
        mode,
        salt: "model-salt",
        userAgent: device.userAgent,
      });

      if (mode === "persistent") {
        expect(visitor.issueCookie).toBe(cookie === undefined);

        if (cookie !== undefined) {
          expect(visitor.anonymousId).toBe(cookie);
        }

        cookies.set(step.device, visitor.anonymousId);
        continue;
      }

      expect(visitor.issueCookie).toBe(false);
      const key = `${day}|${device.ip}|${device.userAgent}`;
      const previous = seen.get(key);

      if (previous !== undefined) {
        expect(visitor.anonymousId).toBe(previous);
      }

      seen.set(key, visitor.anonymousId);
      const today = idsByDay.get(day) ?? new Set<string>();
      today.add(visitor.anonymousId);
      idsByDay.set(day, today);
    }

    const days = [...idsByDay.values()];

    const repeated = days.flatMap((ids, index) =>
      days
        .slice(index + 1)
        .flatMap((later) => [...ids].filter((id) => later.has(id)))
    );

    expect(repeated).toStrictEqual([]);
  }).pipe(Effect.provide(webCryptoLayer));

describe("visitor identity model", () => {
  it.effect.prop(
    "persistent ids survive every visit that keeps the cookie and are reissued when it is lost",
    { steps: commands },
    ({ steps }) => runSession("persistent", steps)
  );

  it.effect.prop(
    "daily ids are stable within a day, never set a cookie, and never repeat across days",
    { steps: commands },
    ({ steps }) => runSession("daily", steps)
  );
});
